window.MOCK_QUESTIONS=[{"q": "Tell me about your home. What does it look like, and what do you like most about it?", "g": "집의 구조, 분위기, 가장 좋아하는 점을 구체적으로 설명하세요."}, {"q": "Describe your neighborhood. What places do you often visit there?", "g": "동네의 특징과 자주 방문하는 장소를 말하세요."}, {"q": "Tell me about a memorable experience you had at a restaurant.", "g": "언제, 누구와, 무슨 일이 있었는지 순서대로 말하세요."}, {"q": "Describe a trip that left a strong impression on you.", "g": "여행지, 활동, 느낌과 기억에 남는 이유를 말하세요."}, {"q": "What do you usually do in your free time?", "g": "평소 활동과 좋아하게 된 이유를 설명하세요."}, {"q": "Compare the way you spend your weekends now with the past.", "g": "과거와 현재의 차이를 구체적으로 비교하세요."}, {"q": "Tell me about a problem you had while using your phone and how you solved it.", "g": "문제 발생, 대응, 결과 순서로 말하세요."}, {"q": "Call a restaurant and ask three or four questions before making a reservation.", "g": "시간, 인원, 메뉴, 주차 등을 질문하세요."}, {"q": "You cannot make it to an appointment. Call your friend, explain, and suggest alternatives.", "g": "사과, 이유, 대안 두 가지를 말하세요."}, {"q": "Describe the weather in your area and how it affects your routine.", "g": "계절별 날씨와 일상 변화까지 연결하세요."}, {"q": "Tell me about your favorite exercise and why you enjoy it.", "g": "운동 방식, 빈도, 장점, 경험을 설명하세요."}, {"q": "Describe a recent shopping experience that did not go as planned.", "g": "상품 문제와 교환·환불 과정을 말하세요."}];